pub fn binary64_model(model: &Model) -> Result<Binary64Model, String> {
    let nodes: Vec<FrameNode> = model
        .nodes
        .iter()
        .enumerate()
        .map(|(k, p)| FrameNode::new(k, *p).map_err(|e| format!("{e:?}")))
        .collect::<Result<_, _>>()?;
    let frames = model
        .members
        .iter()
        .map(|m| {
            let section = FrameSection::new(
                m.elastic_modulus,
                m.shear_modulus,
                m.area,
                m.second_moment_y,
                m.second_moment_z,
                m.torsion_constant,
            )
            .map_err(|e| format!("{e:?}"))?;
            FrameElement::new(
                nodes[m.node_i as usize],
                nodes[m.node_j as usize],
                section,
                m.y_reference,
            )
            .map_err(|e| format!("{e:?}"))
        })
        .collect::<Result<Vec<_>, _>>()?;
    let mut springs = Vec::new();
    for s in &model.springs {
        match s.axis {
            Some(a) => springs.push((s.node as usize * 6 + a, s.stiffness)),
            None => return Err("a directional spring has no binary64 form".into()),
        }
    }
    let n = model.nodes.len() * 6;
    let mut force = vec![0.0; n];
    for (node, c, v, _) in &model.loads {
        force[*node as usize * 6 + c] += v;
    }
    let restrained: Vec<usize> = model
        .constraints
        .iter()
        .map(|&(node, c)| node as usize * 6 + c)
        .collect();
    let free = (0..n).filter(|g| !restrained.contains(g)).collect();
    let mut prescribed: Vec<(usize, f64)> = restrained.iter().map(|&g| (g, 0.0)).collect();
    prescribed.sort_by_key(|p| p.0);
    Ok(Binary64Model {
        node_count: model.nodes.len(),
        frames,
        springs,
        force,
        free,
        prescribed,
    })
}
pub fn pattern_entries(model: &Model) -> usize {
    let n = model.nodes.len();
    let mut touched = vec![false; n];
    let mut pairs: BTreeSet<(u32, u32)> = BTreeSet::new();
    for m in &model.members {
        touched[m.node_i as usize] = true;
        touched[m.node_j as usize] = true;
        if m.node_i != m.node_j {
            pairs.insert((m.node_i, m.node_j));
            pairs.insert((m.node_j, m.node_i));
        }
    }
    let mut spring_entries: BTreeSet<(u32, usize, usize)> = BTreeSet::new();
    for s in &model.springs {
        if touched[s.node as usize] {
            continue;
        }
        match s.axis {
            Some(a) => {
                spring_entries.insert((s.node, a, a));
            }
